__d(function(a,o,e,r,s,i,u){s.exports={titulo:"Termos de Uso",versao:"Vers\xe3o de 7 de novembro de 2026",secoes:[{titulo:"Em resumo",paragrafos:["O Simb\xf3 \xe9 um guia gratuito de lugares em S\xe3o Paulo. Voc\xea usa sem conta.","A gente escolhe e organiza os Lugares, mas n\xe3o vende nada e n\xe3o faz reserva. Pre\xe7o e hor\xe1rio podem mudar: confirme com o Lugar antes de sair.","Ao usar o Simb\xf3, voc\xea concorda com estes termos. Se n\xe3o concordar, \xe9 s\xf3 n\xe3o usar."]},{titulo:"Quem oferece",paragrafos:["O Simb\xf3, que antes se chamava Rol\xea SP, \xe9 um projeto de Ant\xf4nio. Para falar com a gente, escreva para antonio@simbo.app.br."]},{titulo:"De onde v\xeam as informa\xe7\xf5es",paragrafos:["Os Lugares s\xe3o escolhidos pela nossa curadoria, a partir de fontes p\xfablicas, como sites e perfis oficiais. Usamos ferramentas de intelig\xeancia artificial para reunir e organizar os dados. Nem todo texto \xe9 revisado antes de ir ao ar, e a maioria dos Lugares ainda n\xe3o foi conferida pela equipe: a p\xe1gina do Lugar avisa quando \xe9 assim.","Nem todo Lugar foi visitado por n\xf3s. S\xf3 dizemos que fomos a um Lugar quando isso aconteceu de verdade.","Mesmo com esse cuidado, uma informa\xe7\xe3o pode estar errada ou desatualizada. Um Lugar pode fechar, mudar de pre\xe7o, de hor\xe1rio ou de endere\xe7o sem que a gente saiba na hora. O aviso de que a informa\xe7\xe3o ainda precisa ser confirmada aparece no pr\xf3prio Lugar."]},{titulo:"Sua rela\xe7\xe3o com os Lugares",paragrafos:["O atendimento, os pre\xe7os, a seguran\xe7a e o que \xe9 servido s\xe3o responsabilidade de cada Lugar. Qualquer compra ou reserva \xe9 feita diretamente com ele.","Alguns Lugares s\xe3o bares e casas noturnas e vendem bebida alco\xf3lica. A venda \xe9 proibida para menores de 18 anos. Regras de idade e de entrada s\xe3o definidas por cada Lugar e pela lei.","Se um bot\xe3o levar voc\xea a uma rota, ao WhatsApp, ao Instagram ou ao site de um Lugar, voc\xea passa a usar outro servi\xe7o, com regras pr\xf3prias."]},{titulo:"Publicidade",paragrafos:["Nenhum Lugar paga para entrar no guia nem para subir na ordem. O Simb\xf3 pode exibir publicidade, e toda pe\xe7a paga ser\xe1 identificada com o selo \"Parceiro\"."]},{titulo:"Notas",paragrafos:["D\xea nota s\xf3 a Lugares em que voc\xea esteve, com a sua opini\xe3o verdadeira. \xc9 uma nota por aparelho, de 1 a 5, e dar nota marca o Lugar como J\xe1 fui.","A m\xe9dia mostra o que as pessoas responderam, n\xe3o a opini\xe3o do Simb\xf3. Ela nunca muda a ordem padr\xe3o do guia nem o Me Surpreenda.","Podemos desconsiderar notas que pare\xe7am autom\xe1ticas, combinadas ou feitas para prejudicar ou favorecer um Lugar."]},{titulo:"Coment\xe1rios",paragrafos:["Comente s\xf3 sobre Lugares em que voc\xea esteve. Seu coment\xe1rio aparece na hora, para todo mundo, sem seu nome, junto com a nota que voc\xea deu, e voc\xea pode editar ou tirar quando quiser.","O que voc\xea escreve \xe9 responsabilidade sua. N\xe3o publique ofensa, discrimina\xe7\xe3o, mentira, propaganda, contato ou dados pessoais de ningu\xe9m. Links, e-mails e telefones n\xe3o s\xe3o aceitos.","O coment\xe1rio mostra a opini\xe3o de quem escreveu, n\xe3o a do Simb\xf3. Qualquer pessoa pode denunciar um coment\xe1rio: com tr\xeas den\xfancias ele sai do ar at\xe9 a gente olhar, e podemos esconder ou apagar o que descumprir estes termos.","Ao publicar, voc\xea autoriza o Simb\xf3 a mostrar o coment\xe1rio no app e no site, de gra\xe7a, enquanto ele estiver publicado."]},{titulo:"Sugest\xf5es",paragrafos:["Voc\xea pode sugerir lugares. Sugerir n\xe3o garante entrada no guia, e pode ser que a gente n\xe3o responda.","Envie s\xf3 informa\xe7\xf5es que voc\xea pode compartilhar, sem dados pessoais de ningu\xe9m e sem conte\xfado ofensivo ou ilegal. Ao enviar, voc\xea autoriza o Simb\xf3 a usar a sugest\xe3o, de gra\xe7a, para pesquisar o lugar e escrever sobre ele."]},{titulo:"O que n\xe3o fazer",paragrafos:["N\xe3o use rob\xf4s para copiar o cat\xe1logo ou para enviar notas e sugest\xf5es. N\xe3o tente invadir, sobrecarregar ou atrapalhar o Simb\xf3. N\xe3o copie o cat\xe1logo para outro produto.","Se isso acontecer, podemos bloquear o acesso e apagar o que foi enviado."]},{titulo:"Nome, textos e fotos",paragrafos:["O nome Simb\xf3, a logo, os textos e a sele\xe7\xe3o dos Lugares pertencem ao projeto. Voc\xea pode compartilhar links e falar do que encontrou aqui. Para usar o conte\xfado de outro jeito, pe\xe7a antes.","As fotos e os nomes dos Lugares pertencem aos seus donos. A origem das fotos est\xe1 em \"Cr\xe9ditos das imagens\", na aba Voc\xea."]},{titulo:"Se voc\xea representa um Lugar",paragrafos:["Para corrigir uma informa\xe7\xe3o, retirar uma foto ou pedir que o Lugar saia do guia, escreva para antonio@simbo.app.br com o link dele. Vamos analisar e responder."]},{titulo:"Disponibilidade",paragrafos:["O Simb\xf3 \xe9 gratuito e est\xe1 em evolu\xe7\xe3o. Recursos podem mudar, sair do ar ou acabar, e nem sempre ser\xe1 poss\xedvel avisar antes.","Salvos e J\xe1 fui ficam s\xf3 no seu aparelho. Se voc\xea limpar os dados do navegador ou trocar de aparelho, eles podem se perder."]},{titulo:"Responsabilidade",paragrafos:["Fazemos o poss\xedvel para o guia ser \xfatil e correto, mas n\xe3o garantimos que toda informa\xe7\xe3o esteja certa o tempo todo. Por isso, confirme o que for importante antes de sair.","Nada aqui tira os direitos que a lei garante a voc\xea, inclusive os do C\xf3digo de Defesa do Consumidor."]},{titulo:"Seus dados",paragrafos:["Como tratamos seus dados est\xe1 na Pol\xedtica de Privacidade, na aba Voc\xea."]},{titulo:"Mudan\xe7as",paragrafos:["Se estes termos mudarem, a vers\xe3o nova aparece aqui com a data atualizada. Se a mudan\xe7a for importante, avisamos no pr\xf3prio Simb\xf3."]},{titulo:"Lei aplic\xe1vel",paragrafos:["Estes termos seguem a lei brasileira. Se houver um conflito, voc\xea pode recorrer \xe0 Justi\xe7a da cidade onde mora."]}]}},998,[]);